using System;using System.IO;using System.Linq;using System.Collections;using System.Reflection;using UnityEngine;using UnityEngine.UI;using Assets.Script.DynamicCards;using Cynthia.Card;
public static class MotionWork{public static void Run(){new GameObject("Final framing UI evidence").AddComponent<FinalFramingUi>();}}
public class FinalFramingUi:MonoBehaviour{
const string W="C:/UnityProjects/LegacyGwent/work/DynamicCards/MotionIntegrity/ScrollAndFramingRepair/FinalUIPoseLocked/";
object F(object o,string n)=>o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);
void Save(DynamicCardView v,string label){var rt=(RenderTexture)F(v,"texture");if(rt==null)return;var c=(Camera)F(v,"renderCamera");c.Render();var old=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);t.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);t.Apply();RenderTexture.active=old;File.WriteAllBytes(W+label+"-"+F(v,"artId")+"-"+((bool)F(v,"preview")?"large":"small")+".png",t.EncodeToPNG());Destroy(t);var model=(GameObject)F(v,"model");var image=(Image)F(v,"art");var big=image.GetComponentInParent<ArtCard>();var small=image.GetComponentInParent<CardShowInfo>();var border=(big!=null?big.CardBorder:small.CardBorder).rectTransform;var corners=new Vector3[4];((RawImage)F(v,"surface")).rectTransform.GetWorldCorners(corners);float inset=(border.rect.yMax-border.InverseTransformPoint(corners[1]).y)/border.rect.width;File.AppendAllText(W+"geometry.txt",label+" "+F(v,"artId")+" large="+F(v,"preview")+" source="+((DynamicCardEntry)F(v,"entry")).id+" camera="+model.transform.InverseTransformPoint(c.transform.position).ToString("F6")+" rot="+c.transform.rotation.ToString("F6")+" m12="+c.projectionMatrix.m12+" topInset="+inset+"\n");}
IEnumerator Start(){Directory.CreateDirectory(W);Time.timeScale=1;var ids=new[]{"32013","13001","61001","13004"};var e=Resources.FindObjectsOfTypeAll<EditorInfo>().First(x=>x.gameObject.scene.IsValid());e.MainUI.SetActive(false);e.EditorUI.SetActive(true);e.OpenEditor(false);e.LeftSwitchMenu.anchoredPosition=new Vector2(-1700,0);e.RightSwitchMenu.anchoredPosition=new Vector2(1700,0);var cards=GwentMap.GetCards(isHasAgent:true).Where(x=>ids.Contains(x.CardId)).ToList();e.SetShowCardInfo(cards);foreach(var id in ids){e.SelectSwitchUICard(cards.First(x=>x.CardId==id));yield return new WaitForSecondsRealtime(10);Time.timeScale=0;var speeds=new System.Collections.Generic.Dictionary<Animator,float>();foreach(var v in FindObjectsOfType<DynamicCardView>()){var model=(GameObject)F(v,"model");if(model==null)continue;foreach(var a in model.GetComponentsInChildren<Animator>(true)){if(a.runtimeAnimatorController==null)continue;var state=a.GetCurrentAnimatorStateInfo(0);speeds[a]=a.speed;a.speed=0;a.Play(state.fullPathHash,0,id=="13001"?.1f:.5f);a.Update(0);}v.GetType().GetField("age",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(v,5f);}yield return null;foreach(var v in FindObjectsOfType<DynamicCardView>())Save(v,id);ScreenCapture.CaptureScreenshot(W+id+"-screen.png");yield return new WaitForSecondsRealtime(.3f);foreach(var pair in speeds)pair.Key.speed=pair.Value;Time.timeScale=1;}yield return new WaitForSecondsRealtime(2);foreach(var v in FindObjectsOfType<DynamicCardView>())Save(v,"iris-motion-A");yield return new WaitForSecondsRealtime(3);foreach(var v in FindObjectsOfType<DynamicCardView>())Save(v,"iris-motion-B");File.WriteAllText(W+"done.txt","OK timeScale="+Time.timeScale);Destroy(gameObject);}}
